import{_ as d,o as e,c as o,ah as r}from"./chunks/framework.DjU4PSOm.js";const g=JSON.parse('{"title":"또리(DDORI) 프로젝트 정리","description":"","frontmatter":{"tags":["computer/project"],"date":"2026-11-28T00:00:00.000Z"},"headers":[{"level":2,"title":"한 줄 소개와 기간","slug":"한-줄-소개와-기간","link":"#한-줄-소개와-기간","children":[]},{"level":2,"title":"문제와 해결","slug":"문제와-해결","link":"#문제와-해결","children":[]},{"level":2,"title":"주요 기능","slug":"주요-기능","link":"#주요-기능","children":[{"level":3,"title":"아이 화면 (/child)","slug":"아이-화면-child","link":"#아이-화면-child","children":[]},{"level":3,"title":"보호자 화면 (/guardian)","slug":"보호자-화면-guardian","link":"#보호자-화면-guardian","children":[]},{"level":3,"title":"학습 (/child/learn)","slug":"학습-child-learn","link":"#학습-child-learn","children":[]},{"level":3,"title":"관리자 화면 (/admin)","slug":"관리자-화면-admin","link":"#관리자-화면-admin","children":[]}]},{"level":2,"title":"전체 구조","slug":"전체-구조","link":"#전체-구조","children":[{"level":3,"title":"재난문자에서 보호자 화면까지","slug":"재난문자에서-보호자-화면까지","link":"#재난문자에서-보호자-화면까지","children":[]},{"level":3,"title":"AWS 서비스 (저장소에 실제로 있는 것)","slug":"aws-서비스-저장소에-실제로-있는-것","link":"#aws-서비스-저장소에-실제로-있는-것","children":[]},{"level":3,"title":"AI","slug":"ai","link":"#ai","children":[]},{"level":3,"title":"설계에 있지만 저장소에는 없는 것","slug":"설계에-있지만-저장소에는-없는-것","link":"#설계에-있지만-저장소에는-없는-것","children":[]}]},{"level":2,"title":"기술 스택","slug":"기술-스택","link":"#기술-스택","children":[]},{"level":2,"title":"저장소 구성과 협업 방식","slug":"저장소-구성과-협업-방식","link":"#저장소-구성과-협업-방식","children":[]},{"level":2,"title":"주요 결정(ADR)","slug":"주요-결정-adr","link":"#주요-결정-adr","children":[]},{"level":2,"title":"내가 한 일","slug":"내가-한-일","link":"#내가-한-일","children":[{"level":3,"title":"맡은 영역","slug":"맡은-영역","link":"#맡은-영역","children":[]}]},{"level":2,"title":"남은 일과 한계","slug":"남은-일과-한계","link":"#남은-일과-한계","children":[{"level":3,"title":"열린 이슈 중 중요한 것","slug":"열린-이슈-중-중요한-것","link":"#열린-이슈-중-중요한-것","children":[]},{"level":3,"title":"저장소 문서에 적힌 한계","slug":"저장소-문서에-적힌-한계","link":"#저장소-문서에-적힌-한계","children":[]}]}],"relativePath":"computer/project/AWS-PBL/05. 또리 프로젝트 정리 (2026-11-28).md","filePath":"computer/project/AWS-PBL/05. 또리 프로젝트 정리 (2026-11-28).md"}'),a={name:"computer/project/AWS-PBL/05. 또리 프로젝트 정리 (2026-11-28).md"};function l(i,t,n,c,s,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="또리-ddori-프로젝트-정리" tabindex="-1">또리(DDORI) 프로젝트 정리 <a class="header-anchor" href="#또리-ddori-프로젝트-정리" aria-label="Permalink to &quot;또리(DDORI) 프로젝트 정리&quot;">​</a></h1><blockquote><p>팀 저장소 4개(ddori-frontend, ddori-backend, ddori-docs, frontend)의 <code>main</code> 브랜치와 GitHub PR, 이슈를 읽고 프로젝트 전체를 한 번에 정리했다. 2026-11-28 오전 기준이다. 저장소에서 확인한 것만 적었다.</p></blockquote><h2 id="한-줄-소개와-기간" tabindex="-1">한 줄 소개와 기간 <a class="header-anchor" href="#한-줄-소개와-기간" aria-label="Permalink to &quot;한 줄 소개와 기간&quot;">​</a></h2><p><strong>또리는 어려운 재난문자를 아이가 알아듣는 쉬운 말로 바꿔 주고, 지금 할 일을 하나씩 알려 주고, 아이의 상태를 보호자에게 전해 주는 어린이 재난 대응 도우미다.</strong></p><ul><li>AWS Career Launchpad 경북대학교 PBL 2팀(GenAI 서비스 트랙, 4명)</li><li>기간: 2026-11-14 ~ 11-28. 기획 발표 11-20, 아키텍처 발표 11-21, 최종 발표 11-28</li><li>캐릭터: 아이 곁의 <strong>또또</strong>, 보호자 곁의 <strong>리리</strong>. 둘을 합쳐 &quot;또리&quot;다.</li><li>또리는 공식 재난문자를 대신하지 않는다. 아이가 공식 재난문자를 이해하고 행동하도록 돕는 보조 서비스다(ddori-docs <code>PROJECT.md</code>).</li></ul><h2 id="문제와-해결" tabindex="-1">문제와 해결 <a class="header-anchor" href="#문제와-해결" aria-label="Permalink to &quot;문제와 해결&quot;">​</a></h2><p>재난문자를 받은 아이에게는 세 가지가 빠져 있다. 또리는 그 세 가지를 하나씩 채운다. 근거 자료와 숫자는 <a href="./03. 최종발표 문제 정의 근거 (2026-11-28).html">03. 최종발표 문제 정의 근거</a>에, 발표에서 한 말은 <a href="./04. 최종발표 대본 (2026-11-28).html">04. 최종발표 대본</a>에 있다.</p><table tabindex="0"><thead><tr><th>빠진 것</th><th>문제</th><th>또리가 하는 일</th></tr></thead><tbody><tr><td>1. 이해</td><td>&quot;저지대&quot;, &quot;대피 권고&quot;처럼 어른도 헷갈리는 말이 많아 무슨 뜻인지 모른다.</td><td>AI가 재난문자를 짧고 쉬운 문장과 단어 풀이로 바꾸고, 소리로도 읽어 준다.</td></tr><tr><td>2. 행동</td><td>뜻을 알아도 지금 무엇을 해야 할지 모른다.</td><td>공식 국민행동요령에서 뽑은 &quot;따라 해요&quot; 행동 카드를 한 단계씩 보여 준다.</td></tr><tr><td>3. 연결</td><td>행동을 해도 안전하다고 알릴 방법이 없고, 보호자는 아이가 어디 있는지 몰라 불안하다.</td><td>아이가 &quot;괜찮아요&quot;나 &quot;도와줘요&quot;를 누르면 보호자에게 바로 가고, &quot;도와줘요&quot;는 위치도 함께 간다. 응답이 없으면 다시 알린다.</td></tr></tbody></table><h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><p>화면은 PWA 하나에 역할별 경로(<code>/child</code>, <code>/guardian</code>, <code>/admin</code>)로 나뉜다.</p><h3 id="아이-화면-child" tabindex="-1">아이 화면 (<code>/child</code>) <a class="header-anchor" href="#아이-화면-child" aria-label="Permalink to &quot;아이 화면 (`/child`)&quot;">​</a></h3><ul><li><strong>홈</strong>: 평소에는 또또와 레벨 진행도가 보인다. 재난 알림이 오면 어느 화면에 있든 홈 알림 화면으로 한 번 보낸다.</li><li><strong>재난 알림</strong>: 쉬운 말 문장과 단어 풀이, 원문 카드, &quot;소리로 듣기&quot; 버튼(서버 음성이 안 되면 브라우저 음성), &quot;따라 해요&quot; 행동 카드가 나온다. 행동 카드는 지진, 비와 물, 불, 더위 4묶음이다.</li><li><strong>응답</strong>: &quot;괜찮아요&quot; 또는 &quot;도와줘요&quot;. &quot;도와줘요&quot;를 누를 때만 위치 권한을 묻고 위치를 보내며, 119 전화 버튼이 나온다.</li><li><strong>대피소 탭</strong>: 아이 동네 대피소를 지도와 목록으로 보여 주고, &quot;내 위치로 찾기&quot;를 누르면 가까운 순 정렬과 걸어가는 길을 보여 준다.</li><li><strong>설정</strong>: 내 정보, 재난 알림 받기(Web Push), 배지 현황, 로그아웃. 재난 중에는 레벨과 배지를 숨긴다.</li></ul><h3 id="보호자-화면-guardian" tabindex="-1">보호자 화면 (<code>/guardian</code>) <a class="header-anchor" href="#보호자-화면-guardian" aria-label="Permalink to &quot;보호자 화면 (`/guardian`)&quot;">​</a></h3><ul><li><strong>홈</strong>: 카드 하나로 아이 상태를 보여 준다. 대기, 응답 대기, 안전, 긴급 4가지이고, 긴급이면 아이 위치를 지도로 보여 준다. 새로고침 없이 실시간(SSE)으로 바뀐다.</li><li><strong>기록 탭</strong>: 지난 알림, 아이 응답, 응답 없음(재알림) 기록</li><li><strong>대피소 탭</strong>: 내 아이 동네의 대피소</li><li><strong>설정</strong>: 연결된 아이, 아이 연결 코드 재발급, 재난 알림 받기</li><li><strong>가입</strong>: 보호자가 먼저 가입하고 아이를 등록하면 6자리 연결 코드가 나온다. 아이는 그 코드로 로그인한다(10분, 한 번만).</li></ul><h3 id="학습-child-learn" tabindex="-1">학습 (<code>/child/learn</code>) <a class="header-anchor" href="#학습-child-learn" aria-label="Permalink to &quot;학습 (`/child/learn`)&quot;">​</a></h3><ul><li><strong>레슨</strong>: 재난 종류별 섹션(지진, 물, 불, 더위)에서 레슨을 하나씩 연다. 앞 레슨을 끝내야 다음 레슨이 열린다.</li><li><strong>퀴즈</strong>: OX, 객관식, 순서 맞히기. 틀린 문제는 다시 풀고, 처음에 틀린 수에 따라 포인트를 받는다. 30포인트마다 레벨이 오른다.</li><li><strong>배지</strong>: 첫 레슨 완료 배지와 재난별 배지(섹션 레슨 3개 완료)</li><li><strong>또또에게 묻기</strong>: 아이 질문에 행동요령 원문을 근거로 답하고, 근거 문장을 &quot;자세히 보기&quot;로 보여 준다. 근거를 못 찾으면 지어내지 않고 모른다고 답한다.</li><li><strong>재난 중 잠금</strong>: 응답하지 않은 재난 알림이 있으면 학습 탭이 잠기고 홈으로 보낸다. 퀴즈보다 지금 할 행동이 먼저다.</li></ul><h3 id="관리자-화면-admin" tabindex="-1">관리자 화면 (<code>/admin</code>) <a class="header-anchor" href="#관리자-화면-admin" aria-label="Permalink to &quot;관리자 화면 (`/admin`)&quot;">​</a></h3><ul><li><strong>모의 재난문자</strong>: 지역, 긴급 단계, 재난 종류, 문구를 넣거나 미리 만든 예시를 골라 모의 재난문자를 보낸다. 최근 발송 내역도 본다. 시연에서 알림을 일으키는 장치다.</li><li><strong>레슨 만들기와 문제 검수</strong>: 섹션을 고르고 주제를 넣으면 AI가 문제 후보를 만든다. 관리자가 검수하고 고친 문제 4개를 레슨으로 저장하면 바로 아이에게 보인다.</li></ul><h2 id="전체-구조" tabindex="-1">전체 구조 <a class="header-anchor" href="#전체-구조" aria-label="Permalink to &quot;전체 구조&quot;">​</a></h2><h3 id="재난문자에서-보호자-화면까지" tabindex="-1">재난문자에서 보호자 화면까지 <a class="header-anchor" href="#재난문자에서-보호자-화면까지" aria-label="Permalink to &quot;재난문자에서 보호자 화면까지&quot;">​</a></h3><ol><li><strong>수집</strong>: EventBridge Scheduler가 수집 Lambda(Python)를 실행하고, Lambda가 재난문자를 SQS에 넣는다. <ul><li>시드니 리전에서는 정부 재난문자 API에 연결되지 않는다. 그래서 Lambda는 S3에 저장한 과거 실제 재난문자를 보내는 &quot;재생 모드&quot;로 배포했다.</li><li>시연에서는 관리자 화면의 모의 재난문자 API가 같은 처리 로직을 부른다.</li></ul></li><li><strong>저장</strong>: EC2의 Spring Boot가 SQS에서 메시지를 받아 일련번호로 중복을 거르고 RDS(PostgreSQL)에 저장한다.</li><li><strong>쉬운 말 변환</strong>: Vertex AI Gemini가 쉬운 문장과 단어 풀이를 만든다. 앱 검사기와 Bedrock Guardrail이 원문 밖 내용을 막는다. 막히거나 실패하면 재난 종류별 기본 문장을 쓴다.</li><li><strong>알림</strong>: 아이 지역에 맞는 아이와 그 보호자에게 Web Push를 보내고, 보호자 화면에는 SSE 이벤트를 보낸다.</li><li><strong>응답</strong>: 아이가 &quot;괜찮아요&quot; / &quot;도와줘요&quot;(+ 위치)를 보내면 CloudFront를 거쳐 EC2가 저장하고, 보호자에게 SSE와 Web Push로 알린다.</li><li><strong>무응답 재알림</strong>: 알림을 만들 때 EventBridge Scheduler에 일회성 일정을 건다(기본 3분 뒤, 3분 간격, 최대 2회). 일정이 SQS로 만료 메시지를 보내면, 아직 응답하지 않은 아이와 그 보호자에게 다시 알린다.</li></ol><h3 id="aws-서비스-저장소에-실제로-있는-것" tabindex="-1">AWS 서비스 (저장소에 실제로 있는 것) <a class="header-anchor" href="#aws-서비스-저장소에-실제로-있는-것" aria-label="Permalink to &quot;AWS 서비스 (저장소에 실제로 있는 것)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>서비스</th><th>하는 일</th><th>근거</th></tr></thead><tbody><tr><td>Amazon S3 + CloudFront</td><td>PWA 정적 파일 배포. <code>/api/*</code>는 백엔드 CloudFront로 보낸다.</td><td>ddori-frontend <code>infra/frontend.yaml</code></td></tr><tr><td>CloudFront</td><td>백엔드 HTTPS 진입점(CloudFront → EC2)</td><td>ddori-backend <code>infra/app.yaml</code></td></tr><tr><td>VPC, EC2</td><td>Spring Boot API 서버(<code>t4g.small</code> 한 대, systemd). EC2는 CloudFront IP만 받는다. NAT Gateway와 ALB는 쓰지 않는다.</td><td><code>network.yaml</code>, <code>app.yaml</code>, ADR 0010</td></tr><tr><td>RDS for PostgreSQL</td><td>계정, 알림, 응답, 문제 은행, 학습 기록, 배지 저장(프라이빗 서브넷)</td><td><code>db.yaml</code></td></tr><tr><td>EventBridge Scheduler</td><td>재난문자 수집 일정, 무응답 재알림 일회성 일정</td><td><code>collector.yaml</code>, <code>reminder.yaml</code></td></tr><tr><td>AWS Lambda</td><td>재난문자 수집(재생 모드)</td><td><code>lambda/collector.py</code></td></tr><tr><td>Amazon SQS</td><td>재난문자 큐, 재알림 타이머 큐(DLQ 포함)</td><td><code>collector.yaml</code>, <code>reminder.yaml</code></td></tr><tr><td>Bedrock Knowledge Bases (관리형) + S3</td><td>국민행동요령 문서 7개를 근거로 검색(<code>Retrieve</code>)</td><td><code>ai.yaml</code></td></tr><tr><td>Bedrock Guardrails</td><td>쉬운 말 변환용과 Q&amp;A용 Guardrail을 따로 두고 <code>ApplyGuardrail</code>로 출력 검사</td><td><code>ai.yaml</code></td></tr><tr><td>Amazon Polly</td><td>쉬운 문장을 음성(MP3)으로 합성</td><td><code>voice.yaml</code>, <code>PollyVoiceSynthesizer</code></td></tr><tr><td>Secrets Manager, SSM Parameter Store</td><td>DB 비밀번호와 서버 설정 값 보관</td><td><code>db.yaml</code>, 백엔드 README</td></tr><tr><td>SSM Run Command, Session Manager</td><td>자동 배포 실행, SSH 없이 서버 접속</td><td><code>deploy.yaml</code></td></tr><tr><td>IAM (GitHub OIDC)</td><td>GitHub Actions가 AWS 키 없이 배포 역할을 맡는다.</td><td><code>deploy.yaml</code>, <code>frontend.yaml</code></td></tr><tr><td>CloudWatch Logs</td><td>수집 Lambda 로그 그룹. 앱 서버 로그는 CloudWatch로 보내지 않는다.</td><td><code>collector.yaml</code>, 백엔드 README</td></tr></tbody></table><h3 id="ai" tabindex="-1">AI <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>기능</th><th>생성</th><th>근거 검색</th><th>출력 검사</th></tr></thead><tbody><tr><td>쉬운 말 변환</td><td>Vertex AI <code>gemini-3.5-flash-lite</code></td><td>없음(원문 기준)</td><td><code>EasyMessageValidator</code> + Guardrail <code>dodam-easy-message</code></td></tr><tr><td>또또에게 묻기(Q&amp;A)</td><td>Vertex AI <code>gemini-3.5-flash-lite</code></td><td>Bedrock KB <code>Retrieve</code></td><td><code>QaEvidenceSelector</code> + Guardrail <code>dodam-qa</code></td></tr><tr><td>훈련 문제 후보 생성</td><td>Vertex AI <code>gemini-4-hydrogen</code></td><td>Bedrock KB <code>Retrieve</code></td><td>형식 검사 + 근거 문장 대조, 관리자 검수</td></tr><tr><td>음성</td><td>Amazon Polly(기본 <code>Seoyeon</code>, <code>generative</code>)</td><td></td><td></td></tr></tbody></table><ul><li>처음 설계는 생성도 Bedrock 모델이었다. 그런데 새 계정의 Bedrock 모델 호출 할당량이 0이었고, 11-25부터는 계정 접근 제한으로 아예 막혔다. 그래서 생성은 Vertex AI Gemini로 바꾸고, Bedrock은 근거 검색과 출력 검사만 맡겼다(ddori-docs <code>ARCHITECTURE.md</code>).</li></ul><h3 id="설계에-있지만-저장소에는-없는-것" tabindex="-1">설계에 있지만 저장소에는 없는 것 <a class="header-anchor" href="#설계에-있지만-저장소에는-없는-것" aria-label="Permalink to &quot;설계에 있지만 저장소에는 없는 것&quot;">​</a></h3><ul><li><strong>Cognito</strong>: ADR 0007에서 Cognito로 정했다. 하지만 백엔드 코드는 Spring Security가 JWT를 직접 발급한다(보호자 24시간, 아이 30일). Cognito 리소스와 코드는 저장소에 없다.</li><li><strong>Amazon Location Service</strong>: 발표 전까지 지도 리소스와 키가 없었다. 그래서 시연 기간에는 MapLibre + 오픈스트리트맵 타일 + TMAP 보행자 경로로 대신했다(ADR 0012, 제안 상태).</li><li><strong>전체 아키텍처 그림</strong>: 아직 Vertex AI 전환을 반영하지 않았고, 문서가 그림보다 최신이다.</li></ul><h2 id="기술-스택" tabindex="-1">기술 스택 <a class="header-anchor" href="#기술-스택" aria-label="Permalink to &quot;기술 스택&quot;">​</a></h2><table tabindex="0"><thead><tr><th>영역</th><th>스택 (버전은 <code>package.json</code>, <code>build.gradle</code>, README 기준)</th></tr></thead><tbody><tr><td>프론트엔드</td><td>TypeScript 6.0.3, React 19.3.1, Vite 8.3.8, React Router 8.5.2, TanStack Query 5.108.2, Tailwind CSS 4.3.5, openapi-fetch 0.17.0(타입은 openapi-typescript 7.13.0으로 Swagger에서 생성), MapLibre GL JS 6.17.0, vite-plugin-pwa 2.0.0 + workbox 7.4.1(서비스 워커, Web Push), Node.js 24</td></tr><tr><td>백엔드</td><td>Java 21(Amazon Corretto), Spring Boot 4.1.2(Web MVC, Data JPA, Security, OAuth2 Resource Server로 JWT 검증, Validation, Actuator), Flyway, PostgreSQL 17, springdoc-openapi 3.2.0(Swagger), AWS SDK for Java v2 2.59.7(SQS, Scheduler, Bedrock Agent Runtime, Bedrock Runtime, Polly), web-push 5.1.2(VAPID), Lombok, Gradle</td></tr><tr><td>수집 Lambda</td><td>Python 3.13(표준 라이브러리 + boto3)</td></tr><tr><td>인프라</td><td>AWS CloudFormation(YAML). 백엔드 <code>infra/</code>에 스택 9개(<code>dodam-*</code>), 프론트 <code>infra/</code>에 스택 1개(<code>ddori-frontend</code>). 리전은 시드니(<code>ap-southeast-2</code>)</td></tr><tr><td>테스트</td><td>프론트: Vitest 5.1.1, React Testing Library 16.3.3, MSW 3.0.7(<code>?scenario=</code> 로 로딩, 빈, 오류, 오프라인 등 상태 흉내). 백엔드: JUnit + Testcontainers(PostgreSQL). Lambda: pytest, 템플릿 검사 cfn-lint</td></tr><tr><td>배포</td><td>GitHub Actions. 프론트는 CI(typecheck, lint, test, build) 통과 뒤 S3에 올리고 CloudFront 캐시를 무효화한다. 백엔드는 CI(<code>gradlew build</code>, pytest) 통과 뒤 jar를 S3에 올리고 SSM Run Command로 EC2에 배포하며, health 확인이 실패하면 이전 버전으로 되돌린다. 둘 다 GitHub OIDC로 AWS 역할을 맡는다.</td></tr></tbody></table><h2 id="저장소-구성과-협업-방식" tabindex="-1">저장소 구성과 협업 방식 <a class="header-anchor" href="#저장소-구성과-협업-방식" aria-label="Permalink to &quot;저장소 구성과 협업 방식&quot;">​</a></h2><p>저장소는 모두 비공개다. 아래 링크는 팀원만 열린다.</p><table tabindex="0"><thead><tr><th>저장소</th><th>역할</th><th>PR</th><th>이슈</th></tr></thead><tbody><tr><td><a href="https://github.com/knu-aws-team2/ddori-frontend" target="_blank" rel="noreferrer">ddori-frontend</a></td><td>지금 쓰는 프론트엔드(PWA). 프론트 배포 스택 포함</td><td>86 (머지 85, 닫힘 1)</td><td>89 (열림 7, 닫힘 82)</td></tr><tr><td><a href="https://github.com/knu-aws-team2/ddori-backend" target="_blank" rel="noreferrer">ddori-backend</a></td><td>Spring Boot, 수집 Lambda, CloudFormation 템플릿</td><td>62 (모두 머지)</td><td>58 (열림 3, 닫힘 55)</td></tr><tr><td><a href="https://github.com/knu-aws-team2/ddori-docs" target="_blank" rel="noreferrer">ddori-docs</a></td><td>공통 문서: 기획, 기능 목록, 평가 기준, 아키텍처, ADR</td><td>0</td><td>4 (모두 닫힘)</td></tr><tr><td><a href="https://github.com/knu-aws-team2/frontend" target="_blank" rel="noreferrer">frontend</a></td><td>예전 프론트엔드 저장소. 지금은 쓰지 않는다.</td><td>8 (머지 2, 열림 6)</td><td>19 (열림 18, 닫힘 1)</td></tr></tbody></table><p>PR, 이슈 개수는 2026-11-28 오전에 <code>gh</code> 로 센 값이다. GitHub에서 저장소 번호는 PR과 이슈가 같이 쓴다.</p><ul><li><strong>문서 위치</strong>: 기능, 아키텍처, ADR은 ddori-docs에 둔다. API 명세는 백엔드 Swagger가 원본이고, 프론트는 거기서 타입을 만든다. 같은 내용은 한 곳에만 쓰고 링크로 잇는다.</li><li><strong>이슈</strong>: 코드가 바뀌는 저장소에 만들고, 제목에 <code>FEATURES.md</code>의 기능 ID를 붙인다(예: <code>[ALERT-04] 아이 응답 저장 API</code>). 하루 안에 끝낼 크기로 나눈다. 기획 질문과 ADR 논의는 ddori-docs 이슈로 한다. 라벨은 백엔드가 <code>type:</code>, <code>area:</code>, 프론트가 우선순위 <code>P0</code>~<code>P2</code>와 <code>bug</code>, <code>enhancement</code>, <code>보류</code>를 쓴다.</li><li><strong>브랜치</strong>: <code>main</code>에 직접 커밋하지 않고 기능 브랜치에서 PR로 머지한다(ddori-docs의 단순 문서 수정만 예외). 이름은 <code>feat/&lt;기능ID&gt;-&lt;짧은-영문&gt;</code>이다(예: <code>feat/ALERT-04-child-response</code>).</li><li><strong>커밋</strong>: <code>type(scope): 한국어 요약</code>. type은 feat, fix, docs, refactor, test, chore. AI 공동 작성자 표시와 &quot;Generated with ...&quot; 문구는 넣지 않는다.</li><li><strong>PR 리뷰</strong>: 규칙은 &quot;리뷰 승인 뒤 머지, CI 통과 뒤 머지&quot;다. 조직이 GitHub Free 플랜이라 비공개 저장소에 브랜치 보호를 걸 수 없어서, 머지하는 사람이 Checks를 직접 확인한다. 실제로는 ddori-backend PR 62개 중 38개에 다른 팀원 리뷰가 있었고(승인 23개), ddori-frontend는 86개 중 7개(승인 3개)였다.</li><li><strong>ADR</strong>: 기술을 고른 이유와 대안을 <code>decisions/</code>에 번호를 붙여 남긴다. 결정을 바꿀 때는 옛 ADR을 고치지 않고 새 ADR을 만든 뒤 옛 것을 &quot;대체됨&quot;으로 바꾼다.</li><li><strong>AI 도구</strong>: 각 저장소에 <code>CLAUDE.md</code>와 <code>AGENTS.md</code>를 두고, AI 도구와 팀원이 같은 규칙을 따르게 했다.</li></ul><h2 id="주요-결정-adr" tabindex="-1">주요 결정(ADR) <a class="header-anchor" href="#주요-결정-adr" aria-label="Permalink to &quot;주요 결정(ADR)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>번호</th><th>결정</th><th>한 줄 이유</th></tr></thead><tbody><tr><td>0001</td><td>백엔드는 Spring Boot(EC2) 중심, 수집과 타이머만 EventBridge Scheduler + Lambda + SQS</td><td>연결을 유지하는 실시간 갱신과 DB 로직은 서버가 맡고, 정해진 시간에 도는 일만 따로 뺐다.</td></tr><tr><td>0002</td><td>훈련 문제는 하이브리드: AI가 근거로 만들고 팀이 검수해 문제 은행에 저장</td><td>안전교육은 정답이 틀리면 안 되고, 바로 풀리는 학습 흐름이 필요하다.</td></tr><tr><td>0003</td><td>DB는 RDS for PostgreSQL(계획서는 DynamoDB)</td><td>팀에 DynamoDB 경험이 없고, 보호자와 아이, 알림과 응답처럼 서로 이어진 데이터가 많다.</td></tr><tr><td>0004</td><td>Spring Security + JWT 직접 발급 → 0007로 대체됨</td><td>이메일이 없는 아이를 연결 코드로 로그인시키기 쉬웠다.</td></tr><tr><td>0005</td><td>React Native 앱 → 0006으로 대체됨</td><td>처음 최종 목표가 앱이었다.</td></tr><tr><td>0006</td><td>클라이언트를 PWA로, 배포는 S3 + CloudFront, 알림은 Web Push(SNS 대신)</td><td>2단계 아키텍처 그림과 계획서 보강판을 기준으로 삼았다.</td></tr><tr><td>0007</td><td>인증을 Cognito로</td><td>아키텍처 그림을 따랐다. 구현은 아직 0004 방식이다(위 &quot;설계에 있지만 저장소에는 없는 것&quot;).</td></tr><tr><td>0008</td><td>TypeScript + React + Vite, PWA 하나에 역할별 경로</td><td>S3 정적 배포와 맞고, 배포, 서비스 워커, 로그인 코드가 한 벌이다.</td></tr><tr><td>0009</td><td>IaC는 CloudFormation, 템플릿은 백엔드 <code>infra/</code></td><td>교육에서 배웠고 AWS CLI만으로 쓸 수 있으며, 심사 기준에 IaC가 있다.</td></tr><tr><td>0010</td><td>CloudFront → EC2(퍼블릭) → RDS(프라이빗), NAT와 ALB 없음, systemd + GitHub Actions(OIDC) + SSM 배포</td><td>보안과 크레딧 절약이 먼저였고, 도메인 없이 HTTPS를 쓸 수 있다.</td></tr><tr><td>0011</td><td>근거 검색을 관리형 Knowledge Bases로(S3 Vectors 뺌)</td><td>임베딩 모델 할당량이 0이라 벡터 저장소형 KB는 동기화가 실패했다.</td></tr><tr><td>0012</td><td>시연 기간 지도는 오픈스트리트맵 + TMAP 보행자 경로(제안)</td><td>발표 전까지 Amazon Location 리소스와 키가 없었다.</td></tr></tbody></table><h2 id="내가-한-일" tabindex="-1">내가 한 일 <a class="header-anchor" href="#내가-한-일" aria-label="Permalink to &quot;내가 한 일&quot;">​</a></h2><p>나(dogkim)가 만든 PR은 21개다.</p><table tabindex="0"><thead><tr><th>저장소</th><th>PR</th><th>제목</th><th>상태</th></tr></thead><tbody><tr><td>ddori-backend</td><td>#24</td><td>[SYSTEM-01] 재난문자 수집 Lambda와 SQS 수신</td><td>머지</td></tr><tr><td>frontend</td><td>#17</td><td>[ACCOUNT-01] 로그인 기반과 보호자 가입, 로그인</td><td>열림</td></tr><tr><td>frontend</td><td>#18</td><td>[ACCOUNT-01] 보호자 아이 등록과 연결 코드 발급</td><td>열림</td></tr><tr><td>frontend</td><td>#19</td><td>[ACCOUNT-01] 아이 연결 코드 로그인</td><td>열림</td></tr><tr><td>frontend</td><td>#21</td><td>[ALERT-01] 아이 재난 알림 목록과 상세</td><td>열림</td></tr><tr><td>frontend</td><td>#22</td><td>[ALERT-03] 행동 카드 화면</td><td>열림</td></tr><tr><td>frontend</td><td>#23</td><td>[ALERT-04] 아이 괜찮아요, 도와줘요 응답</td><td>열림</td></tr><tr><td>ddori-frontend</td><td>#43</td><td>[세팅] 화면 경로 뼈대와 MSW 시나리오 설정</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#48</td><td>[API] 인증, 세션, 역할별 경로 보호</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#51</td><td>[세팅] 개발 서버 프록시를 팀 배포 서버(AWS)로 변경</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#52</td><td>[API] 아이 재난 알림 조회와 응답 저장(+ 위치)</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#53</td><td>[API] 보호자 실시간 상태(SSE)와 현황 hook</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#55</td><td>[화면] S-01 시작화면</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#65</td><td>[화면] S-02 보호자 로그인, S-03 아이 연결 코드 로그인</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#66</td><td>[화면] S-04 보호자 회원가입, S-05 가입 완료와 아이 연결 코드</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#67</td><td>[화면] P-01~P-04 보호자 메인과 현황(대기, 응답 대기, 안전, 긴급)</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#74</td><td>[화면] P-05 알림, 응답 기록과 P-06 설정</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#101</td><td>[화면] 탭바 글자 대비, 대피소 탭 등급 배지 빼기와 다듬기</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#110</td><td>[화면] K-08 대피소 탭: 실제 지도와 길 안내</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#124</td><td>[버그] 학습 탭 카드 버튼이 탭바를 가리지 않게 탭바를 앞에 두기</td><td>머지</td></tr><tr><td>ddori-frontend</td><td>#172</td><td>[버그] 재난 알림 첫 화면에서 응답 버튼이 탭바에 가리지 않게 하기</td><td>머지</td></tr></tbody></table><p>frontend(예전 저장소)의 PR 6개는 머지되지 않은 채 남아 있다. 비슷한 기능은 ddori-frontend의 #48(인증), #52(재난 알림과 응답)에 들어 있다. PR 제목의 중간점은 이 노트에서 쉼표로 바꿨다.</p><h3 id="맡은-영역" tabindex="-1">맡은 영역 <a class="header-anchor" href="#맡은-영역" aria-label="Permalink to &quot;맡은 영역&quot;">​</a></h3><ul><li><strong>백엔드 수집 경로</strong>: 재난문자 수집 Lambda와 Spring Boot의 SQS 수신을 만들었다(#24).</li><li><strong>프론트 기반</strong>: 화면 경로 뼈대와 MSW 시나리오, 로그인 세션과 역할별 경로 보호, 개발 서버 프록시를 맡았다.</li><li><strong>API 연결</strong>: 아이 재난 알림 조회와 응답 저장(위치 포함), 보호자 실시간 상태(SSE) 훅을 만들었다.</li><li><strong>화면</strong>: 시작, 로그인, 회원가입과 연결 코드 화면, 보호자 화면 전체(현황 4가지, 기록, 설정), 아이 대피소 탭의 실제 지도와 TMAP 길 안내를 만들었다.</li><li><strong>마무리</strong>: 탭바가 버튼을 가리는 버그 같은 화면 문제를 고쳤다.</li></ul><h2 id="남은-일과-한계" tabindex="-1">남은 일과 한계 <a class="header-anchor" href="#남은-일과-한계" aria-label="Permalink to &quot;남은 일과 한계&quot;">​</a></h2><h3 id="열린-이슈-중-중요한-것" tabindex="-1">열린 이슈 중 중요한 것 <a class="header-anchor" href="#열린-이슈-중-중요한-것" aria-label="Permalink to &quot;열린 이슈 중 중요한 것&quot;">​</a></h3><ul><li>ddori-backend #116 [버그] &quot;괜찮아요&quot;를 눌렀는데도 &quot;아직 대답하지 않았어요&quot; 재알림이 온다.</li><li>ddori-backend #120 지진 3번 행동 카드에 &quot;밖에서&quot; 조건 넣기</li><li>ddori-backend #96 데모 영상용 재난문자 재생 메모</li><li>ddori-frontend #38 데모 시나리오 1~5 세 번 돌려 보기, #39 로딩, 에러, 빈 상태 화면 확인, #41 실제 폰에서 PWA 설치와 화면 확인, #42 README 작성</li><li>ddori-frontend 보류: #105 아이 화면 본문 글자 18px 맞추기, #111 토큰 만료 때 푸시 구독 정리, #123 학습 화면 햅틱 피드백</li></ul><h3 id="저장소-문서에-적힌-한계" tabindex="-1">저장소 문서에 적힌 한계 <a class="header-anchor" href="#저장소-문서에-적힌-한계" aria-label="Permalink to &quot;저장소 문서에 적힌 한계&quot;">​</a></h3><ul><li><strong>실제 재난문자를 받지 못한다.</strong> 시드니 리전에서는 정부 재난문자 API에 연결되지 않아, 과거 실제 문자를 다시 보내는 재생 모드와 모의 재난문자로 시연한다. 실제 문자도 API에 약 10분 늦게 올라온다.</li><li><strong>대피소 데이터</strong>는 시연 지역인 대구광역시 북구의 지진 옥외대피소 63곳뿐이다.</li><li><strong>Guardrail의 한국어 한계</strong>: 근거 검사는 원문 밖 내용은 잘 막지만, 원문과 반대로 말하는 문장은 통과시킬 수 있다. 그래서 앱 검사기를 함께 둔다.</li><li><strong>Web Push</strong>: iOS는 홈 화면에 추가한 PWA(16.4 이상)에서만 받는다. 서버는 알림이 실제로 도착했는지 알기 어렵다.</li><li><strong>서버 한 대 전제</strong>: SSE 연결과 음성 캐시가 서버 메모리에 있다. 서버를 늘리려면 다시 설계해야 한다. refresh token은 없다.</li><li><strong>TMAP 키와 위치</strong>: TMAP 키가 빌드 결과에 들어가 공개되고, 대피소 길을 찾을 때 아이 위치가 TMAP(SK)으로 간다. 시연 뒤에는 키를 폐기하고, 계속 운영하면 백엔드가 대신 부르게 바꾼다.</li><li><strong>설계와 구현의 차이</strong>: Cognito와 Amazon Location Service는 구현하지 않았고, 아키텍처 그림은 Vertex AI 전환 전 상태다.</li><li><strong>목표 수치</strong>: &quot;3초 안에 이해, 1분 안에 첫 행동&quot;은 계획서의 목표값이고 검증하지 않았다.</li><li><strong>아이 연령 범위</strong>는 정하지 않았다. 계획서는 초등학생이고, 팀에서는 스마트폰을 가진 아이로 넓히자는 의견이 있었다.</li></ul>',48)])])}const b=d(a,[["render",l]]);export{g as __pageData,b as default};
